def kth_smallest_path_xor_sum(parent, val, queries):
    n = len(parent)
    children = [[] for _ in range(n)]
    for i in range(1, n):
        children[parent[i]].append(i)

    # Iterative preorder: path xor from the root, euler positions
    xr = [0] * n
    xr[0] = val[0]
    tin = [0] * n
    order = []
    stack = [0]
    while stack:
        u = stack.pop()
        tin[u] = len(order)
        order.append(u)
        for c in children[u]:
            xr[c] = xr[u] ^ val[c]
            stack.append(c)
    size = [1] * n
    for u in reversed(order):
        if u:
            size[parent[u]] += size[u]
    heavy = [max(children[u], key=size.__getitem__, default=-1) for u in range(n)]
    xs = [xr[u] for u in order]  # xor values in euler order

    N = 1 << 17  # xor values are < 2^17 since val[i] <= 1e5
    bit = [0] * (N + 1)
    cnt = [0] * N
    distinct = 0

    def add(x):
        nonlocal distinct
        cnt[x] += 1
        if cnt[x] == 1:
            distinct += 1
            i = x + 1
            while i <= N:
                bit[i] += 1
                i += i & -i

    def remove(x):
        nonlocal distinct
        cnt[x] -= 1
        if cnt[x] == 0:
            distinct -= 1
            i = x + 1
            while i <= N:
                bit[i] -= 1
                i += i & -i

    def kth(k):
        pos = 0
        pw = N
        while pw:
            if pos + pw <= N and bit[pos + pw] < k:
                pos += pw
                k -= bit[pos]
            pw >>= 1
        return pos  # value = (pos + 1) - 1

    qlist = [[] for _ in range(n)]
    for idx, (u, k) in enumerate(queries):
        qlist[u].append((k, idx))
    ans = [-1] * len(queries)

    # DSU on tree (iterative): frames are (node, keep, phase)
    stack = [(0, True, 0)]
    while stack:
        u, keep, phase = stack.pop()
        if phase == 0:
            stack.append((u, keep, 1))
            h = heavy[u]
            if h != -1:
                stack.append((h, True, 0))   # processed after the light children
            for c in children[u]:
                if c != h:
                    stack.append((c, False, 0))
        else:
            add(xr[u])
            h = heavy[u]
            for c in children[u]:
                if c != h:
                    for i in range(tin[c], tin[c] + size[c]):
                        add(xs[i])
            for k, idx in qlist[u]:
                ans[idx] = kth(k) if k <= distinct else -1
            if not keep:
                for i in range(tin[u], tin[u] + size[u]):
                    remove(xs[i])
    return ans
